var BANK_CODE = "100";
var BRANCH_CODE = "01";
function luhnCheckDigit(digits) {
  let sum = 0;
  let alternate = false;
  for (let i = digits.length - 1;i >= 0; i--) {
    let n2 = parseInt(digits[i], 10);
    if (alternate) {
      n2 *= 2;
      if (n2 > 9)
        n2 -= 9;
    }
    sum += n2;
    alternate = !alternate;
  }
  return (10 - sum % 10) % 10;
}
